package org.updraft.betterstatus.model;
public record ServerSnapshot(String name,ServerState state,int players,int maxPlayers,long pingMillis,String motd,String version,boolean maintenance,long lastSuccessMillis,long lastCheckMillis,long stateChangedMillis,long uptimeSinceMillis,String detail) { public ServerSnapshot { name=name==null?"":name; state=state==null?ServerState.UNKNOWN:state; motd=motd==null?"":motd; version=version==null?"":version; detail=detail==null?"":detail; } public long uptimeSeconds(){return uptimeSinceMillis<=0?0:Math.max(0,(System.currentTimeMillis()-uptimeSinceMillis)/1000);} public long downtimeSeconds(){return lastSuccessMillis<=0?0:(state==ServerState.OFFLINE||state==ServerState.UNREACHABLE?Math.max(0,(System.currentTimeMillis()-lastSuccessMillis)/1000):0);} }